// Digests of what the original field's message windows and their opcodes leave on random scenarios,
// generated by the oracle: for each
// seed, 200 ticks of events, the windows' tick and their update, on the scenario
// Testing::GenerateMessageScenario draws.

namespace
{
	std::array<uint8, 20> TickDigest(const FEventContext& Context)
	{
		std::vector<uint8> Bytes = Testing::MessageWindowBytes(Context);
		for (uint32 Address = 0; Address < FEventVariables::AddressEnd; Address += 2)
		{
			const uint16 Value = Context.Variables.Raw(Address);
			Bytes.push_back(static_cast<uint8>(Value));
			Bytes.push_back(static_cast<uint8>(Value >> 8));
		}
		for (const FEventActorState& State : Context.States)
		{
			const auto Layout = Testing::ToOriginalLayout(State);
			Bytes.insert(Bytes.end(), Layout.begin(), Layout.end());
		}
		return FSha1::Hash(Bytes);
	}

	std::string RunScenario(uint32 Seed, const FIso9660& Disc, const FGameFileIndex& Index, const FMesResident& Resident)
	{
		Testing::FScenarioRandom Random(Seed);
		const int32 MapNumber = Testing::MessageScenarioMaps[Random.Below(static_cast<uint32>(Testing::MessageScenarioMaps.size()))];
		const auto Map = LoadFieldMap(Disc.Image(), Index, MapNumber);
		REQUIRE(Map);
		const auto Table = FMessageTable::Parse(Map->Messages);
		REQUIRE(Table);
		const Testing::FMessageScenario Scenario = Testing::GenerateMessageScenario(Random, *Table);
		const auto Scripts = FEventScripts::Parse(Scenario.Section);
		REQUIRE(Scripts);
		FGameState Game;
		std::copy(Scenario.GameState.begin(), Scenario.GameState.end(), Game.Block().begin());

		FEventContext Context;
		Context.Scripts = &*Scripts;
		Context.MapNumber = MapNumber;
		Context.RunningMap = MapNumber;
		Context.GameState = &Game;
		Context.Options = FEventOptions::Original();
		Context.bInitDone = true;
		for (uint32 Variable = 0; Variable < Scenario.Variables.size(); ++Variable)
		{
			Context.Variables.Set(Variable * 2, Scenario.Variables[Variable]);
		}
		for (std::size_t Actor = 0; Actor < Scenario.States.size(); ++Actor)
		{
			const std::span<const uint8> Bytes(Scenario.Records[Actor]);
			FFieldActor& Record = Context.Actors.emplace_back();
			Record.Flags = LittleEndian::ReadU16(Bytes, 0x58);
			for (std::size_t Row = 0; Row < 3; ++Row)
			{
				for (std::size_t Column = 0; Column < 3; ++Column)
				{
					Record.Matrix[Row][Column] = LittleEndian::ReadS16(Bytes, 0x0C + 6 * Row + 2 * Column);
				}
			}
			for (std::size_t Axis = 0; Axis < 3; ++Axis)
			{
				Record.Translation[Axis] = static_cast<int32>(LittleEndian::ReadU32(Bytes, 0x20 + 4 * Axis));
				Record.Position[Axis] = static_cast<int32>(LittleEndian::ReadU32(Bytes, 0x40 + 4 * Axis));
			}
			Context.States.push_back(Testing::FromOriginalLayout(Scenario.States[Actor]));
		}
		Context.PartyActors = {0, static_cast<uint8>(std::min<std::size_t>(1, Scenario.States.size() - 1)), FEventContext::NoActor};
		Context.PartyCharacters = {0, 1, FEventContext::NoActor};
		Context.Camera.GoalViewYaw = Scenario.GoalViewYaw;
		Context.ScriptView.View = Scenario.View;
		Context.ScriptView.ProjectionDistance = Scenario.ProjectionDistance;
		FFieldMessages& Messages = Context.Messages;
		Messages.Table = *Table;
		Messages.Text.Font = &Resident.Font;
		Messages.Text.Tables = &Resident.NameTables;
		Messages.Text.ButtonMap = MesKernelButtonMap;
		Messages.EnterMap();

		FSha1 Hash;
		for (int32 Tick = 0; Tick < Testing::MessageScenarioTicks; ++Tick)
		{
			const Testing::FMessageScenarioPads& Pads = Scenario.Pads[static_cast<std::size_t>(Tick)];
			Messages.bMapEntering = Tick < Scenario.EnteringTicks;
			const auto Error = FEventMachine::Update(Context);
			if (Error)
			{
				FAIL(Error->Message);
			}
			Messages.Tick();
			UpdateFieldMessages(Context, Pads.Pressed, Pads.Repeat, 2);
			if (Tick == Scenario.CloseAllTick)
			{
				Messages.CloseAll();
			}
			Hash.Update(TickDigest(Context));
		}
		return FSha1::ToHex(Hash.Finish());
	}
}

